Uint8List _hex(String h) {
  final o = Uint8List(h.length ~/ 2);
  for (var i = 0; i < o.length; i++) {
    o[i] = int.parse(h.substring(i * 2, i * 2 + 2), radix: 16);
  }
  return o;
}

String _toHex(Uint8List b) =>
    b.map((x) => x.toRadixString(16).padLeft(2, '0')).join();

void main() {
  test('public keys and signatures match the frozen vectors under dart2js', () {
    for (var i = 0; i < vectors.length; i++) {
      final v = vectors[i];
      final sk = _hex(v[0]);
      final msg = _hex(v[1]);
      expect(_toHex(web.publicKeyFromSecret(sk)), v[2], reason: 'public key, vector $i');
      expect(_toHex(web.signDetached(msg, sk)), v[3], reason: 'signature, vector $i');
    }
  });

  test('self-verification round-trips in the browser', () {
    for (final v in vectors) {
      final sig = _hex(v[3]), pk = _hex(v[2]), msg = _hex(v[1]);
      expect(web.verifyDetached(msg, sig, pk), isTrue);
      final bad = Uint8List.fromList(sig)..[10] ^= 0x40;
      expect(web.verifyDetached(msg, bad, pk), isFalse);
    }
  });
}
